// ── Activity Selection — maximum non-overlapping intervals ─────
// Greedy: always pick the activity with the earliest finish time.
// Sort by end time, then scan linearly — O(n log n) total.

function activitySelection(activities) {
  // activities = [{ start, end, name }, ...]
  const sorted = [...activities].sort((a, b) => a.end - b.end);
  const selected = [sorted[0]];
  let lastEnd = sorted[0].end;

  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i].start >= lastEnd) {   // non-overlapping
      selected.push(sorted[i]);
      lastEnd = sorted[i].end;
    }
  }
  return selected;
}

const activities = [
  { start: 1,  end: 4,  name: 'A' },
  { start: 3,  end: 5,  name: 'B' },
  { start: 0,  end: 6,  name: 'C' },
  { start: 5,  end: 7,  name: 'D' },
  { start: 3,  end: 9,  name: 'E' },
  { start: 5,  end: 9,  name: 'F' },
  { start: 6,  end: 10, name: 'G' },
  { start: 8,  end: 11, name: 'H' },
];

console.log(activitySelection(activities).map(a => a.name));
// ["A", "D", "H"]

// ── Why greedy coin change fails for arbitrary denominations ───
// With denominations [1, 3, 4] and target 6:
// Greedy: picks 4 (best <= 6), then 1, then 1 -> 3 coins
// Optimal: 3 + 3 -> 2 coins
// The greedy choice property FAILS here.

function greedyCoinChange(coins, amount) {
  const desc = [...coins].sort((a, b) => b - a);
  const used = [];
  for (const coin of desc) {
    while (amount >= coin) {
      used.push(coin);
      amount -= coin;
    }
  }
  return amount === 0 ? used : null; // null = impossible
}

console.log(greedyCoinChange([1, 5, 10, 25], 36));
// [25, 10, 1]  <- correct for canonical US denominations

console.log(greedyCoinChange([1, 3, 4], 6));
// [4, 1, 1]   <- WRONG: optimal is [3, 3]

// ── Huffman Encoding — greedy optimal prefix-free code ─────────
// Min-heap is simplified here (sort on each push).
// In production, use a proper binary heap for O(n log n).

class MinHeap {
  constructor() { this.data = []; }
  push(node) {
    this.data.push(node);
    this.data.sort((a, b) => a.freq - b.freq);
  }
  pop()  { return this.data.shift(); }
  get size() { return this.data.length; }
}

function buildHuffmanTree(freqMap) {
  const heap = new MinHeap();
  for (const [char, freq] of Object.entries(freqMap)) {
    heap.push({ char, freq, left: null, right: null });
  }
  while (heap.size > 1) {
    const left  = heap.pop();  // least frequent
    const right = heap.pop();  // second least frequent
    heap.push({
      char: null,
      freq: left.freq + right.freq,
      left,
      right
    });
  }
  return heap.pop(); // root
}

function getCodes(node, prefix, codes) {
  prefix = prefix === undefined ? '' : prefix;
  codes  = codes  === undefined ? {} : codes;
  if (!node.left && !node.right) {
    codes[node.char] = prefix || '0'; // single-symbol edge case
    return codes;
  }
  if (node.left)  getCodes(node.left,  prefix + '0', codes);
  if (node.right) getCodes(node.right, prefix + '1', codes);
  return codes;
}

const freqs = { a: 45, b: 13, c: 12, d: 16, e: 9, f: 5 };
const root  = buildHuffmanTree(freqs);
const codes = getCodes(root);
console.log(codes);
// { a: '0', b: '101', c: '100', d: '111', e: '1101', f: '1100' }

// Total bits for a 100-symbol message (one of each frequency):
// a: 45*1 + b: 13*3 + c: 12*3 + d: 16*3 + e: 9*4 + f: 5*4
// = 45 + 39 + 36 + 48 + 36 + 20 = 224 bits
// A naive fixed-width encoding (3 bits each) would use 300 bits.
// Huffman saves ~25% in this example.
const totalBits = Object.entries(freqs).reduce((sum, [ch, freq]) => {
  return sum + freq * codes[ch].length;
}, 0);
console.log('Total bits (Huffman):', totalBits);   // 224
console.log('Total bits (fixed 3):', 100 * 3);    // 300

// ── Fractional Knapsack — greedy is correct here ──────────────
// Sort by value/weight ratio DESC, greedily fill, take fraction last.
// Time: O(n log n)  Space: O(1) extra

function fractionalKnapsack(items, capacity) {
  const sorted = [...items].sort((a, b) =>
    (b.value / b.weight) - (a.value / a.weight)
  );
  let totalValue = 0;
  let remaining  = capacity;
  const taken = [];

  for (const item of sorted) {
    if (remaining <= 0) break;
    const take = Math.min(item.weight, remaining);
    totalValue += take * (item.value / item.weight);
    taken.push({ name: item.name, weight: take });
    remaining -= take;
  }
  return { totalValue, taken };
}

const items = [
  { name: 'A', value: 60,  weight: 10 },   // ratio 6.0
  { name: 'B', value: 100, weight: 20 },   // ratio 5.0
  { name: 'C', value: 120, weight: 30 },   // ratio 4.0
];

console.log(fractionalKnapsack(items, 50));
// totalValue: 240
// taken: [A (10), B (20), C (20/30 fraction)]
// A full (60) + B full (100) + 2/3 of C (80) = 240

// ── Greedy correctness self-check template ────────────────────
// Apply this checklist before committing to greedy:
//
// 1. Identify the greedy criterion:
//    "Always pick the item with the highest value/weight ratio"
//
// 2. Exchange argument:
//    Assume OPT starts differently. Swapping in our greedy choice
//    gives OPT' with totalValue >= OPT.totalValue?
//    For fractional KS: YES — highest ratio item maximises value per unit.
//
// 3. Optimal substructure:
//    After taking as much of the best item as possible, is the rest
//    the same fractional knapsack problem on fewer items?
//    YES — reduce items by one, reduce capacity by amount taken.
